      "id": "checkpoint-rail",
      "kind": "step-rail",
      "presentation": "Place below the explanation and above the experiment. Show the active checkpoint and completed trace here only. Steps represent states, not elapsed time. Reference captures show final-budget.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "trial-roster",
      "kind": "fixed-picture",
      "presentation": "Use four fixed trial rows in alphabetical order. Align each named region with its readout. Highlight candidates participating in the current comparison or allocation. Keep stopped candidates visible; their frozen readouts preserve earlier evidence. No ghost or animation is needed.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "trial-evidence",
      "kind": "value-readout",
      "presentation": "Show cumulative training, validation accuracy, and allocation status beside each trial. Put the allocation entry below the rows as the bound status line. Assume fixed configurations, one validation set, equal epoch costs, and deterministic scores. Higher accuracy wins; alphabetical trial order breaks ties. Accuracy uses a shared percentage scale, rounded to whole percentage points. Epoch counts measure cumulative training from each trial's start. The initial checkpoint follows one epoch; later cumulative budgets double. Keep half the eligible trials at each selection. Survivors resume training rather than restart. Stopped trials never re-enter. All changing measurements come from the selected state's readouts.",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "allocation-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the named trial without covering its readout. Identify the decision and explain its cause. Keep numeric evidence in the readouts only.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    }
  ],
